'use strict';
/** Small original-image pixel fixtures generated by us for deterministic QA.
 * Not photographs, textbook screenshots, OCR model accuracy or private data. */
function paper(width,height){
 const data=new Uint8ClampedArray(width*height*4);
 for(let i=0;i<data.length;i+=4){
  data[i]=255;data[i+1]=255;data[i+2]=255;data[i+3]=255;
 }
 return {width,height,data};
}
function dot(img,x,y){
 x=Math.round(x);y=Math.round(y);
 if(x<0||y<0||x>=img.width||y>=img.height)return;
 const k=4*(y*img.width+x);
 img.data[k]=0;img.data[k+1]=0;img.data[k+2]=0;
}
function line(img,a,b){
 const n=Math.ceil(Math.hypot(b.x-a.x,b.y-a.y)*3);
 for(let j=0;j<=n;j++){
  const t=j/n;
  dot(img,a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t);
 }
}
function circle(img,c,r,start=0,end=360){
 for(let angle=start;angle<=end;angle+=.3){
  const rad=angle*Math.PI/180;
  dot(img,c.x+r*Math.cos(rad),c.y+r*Math.sin(rad));
 }
}
function scenarios(){
 const lineImage=paper(200,180);
 const a={x:20,y:60},b={x:175,y:60};
 line(lineImage,a,b);
 const circleImage=paper(170,170),circleCenter={x:85,y:82};
 circle(circleImage,circleCenter,38);
 const arcImage=paper(190,180),arcCenter={x:80,y:85};
 circle(arcImage,arcCenter,44,10,135);
 const blank=paper(128,128);
 const common=kind=>({kind,coordinateSpace:'original-image-px'});
 return [
  {id:'synthetic-finite-horizontal-line',detector:'line',
   image:lineImage,truth:[{id:'truth_line',...common('line'),from:a,to:b}]},
  {id:'synthetic-closed-circle',detector:'curve',
   image:circleImage,truth:[{id:'truth_circle',...common('circle'),
    center:circleCenter,radius:38}]},
  {id:'synthetic-partial-circular-arc',detector:'curve',
   image:arcImage,truth:[{id:'truth_arc',...common('arc'),
    center:arcCenter,radius:44,coverageDeg:125}]},
  {id:'synthetic-empty-page',detector:'line',
   image:blank,truth:[]}
 ];
}
module.exports={scenarios};
